mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM contracts ct
             JOIN project_applications pa ON pa.application_id = ct.contract_id
    WHERE ct.contract_id = #{contractId}
      AND pa.freelancer_id = #{freelancerId}
)

SELECT contract_id
FROM contract_milestones
WHERE milestone_id = #{milestoneId}

SELECT step_order
FROM contract_milestones
WHERE milestone_id = #{milestoneId}

SELECT status
FROM contract_milestones
WHERE milestone_id = #{milestoneId}

SELECT pa.application_id
FROM project_applications pa
WHERE pa.application_id = #{contractId}
  AND pa.freelancer_id = #{freelancerId}
    LIMIT 1

SELECT pa.project_id
FROM project_applications pa
WHERE pa.application_id = #{contractId}
  AND pa.freelancer_id = #{freelancerId}
    LIMIT 1

SELECT ct.contract_id AS contractId,
ct.freelancer_rating AS freelancerRating, ct.freelancer_experience AS freelancerExperience,
ct.client_rating AS clientRating, ct.client_experience AS clientExperience FROM contracts ct WHERE ct.contract_id = #{contractId}

mapper.update:
UPDATE contracts
SET freelancer_rating = #{rating},
    freelancer_experience = #{experience}
WHERE contract_id = #{contractId}
